{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def event(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert conversion_rate([event("b", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_and_handles_empty_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event("b", 1, False), event("c", 1, None),
                        event("d", 1, False)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_parse_fields_and_skip_lines():
    assert parse_session_log([" \n", "  # comment,0,1", " a , 3 , 1 ",
                              "b, 4, 0", " c, -1, "]) == [
        event("a", 3, True), event("b", 4, False), event("c", -1, None)]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1,yes"])
def test_parse_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log(["  # comment", " ", line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    earlier = event("a", 0, True)
    later = event("a", 3, False)
    b = event("b", 3, True)
    c = event("c", 1, None)
    assert dedupe_sessions([earlier, b, c, later]) == [c, later, b]
    assert dedupe_sessions([]) == []


def test_daily_counts_cover_range_with_gaps_and_ignore_outside():
    events = [event("a", 0, True), event("b", 2, True), event("c", 2, True),
              event("d", 3, None), event("e", 4, False), event("f", 6, True)]
    assert daily_conversion_counts(events, 1, 5) == [0, 2, 0, 0, 0]
    assert daily_conversion_counts([], 2, 4) == [0, 0, 0]
    assert daily_conversion_counts(events, 5, 2) == []


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [event("a", 1, True), event("b", 3, False)],
              "b": [event("c", 5, True)], "empty": []}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 10)["recent"] == 2
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("a", 1, True)], "b": [event("b", 1, True)],
              "a": [event("c", 1, False)], "empty": []}
    assert top_converting_groups(groups, 10) == ["b", "z", "a"]
    assert top_converting_groups(groups, 1) == ["b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]


def test_longest_streak_requires_consecutive_positive_counts():
    assert longest_conversion_streak([1, 2, 0, 1, -1, 1, 2, 3, 0]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
